package com.semes.reqops.domain.knowledge.service; import com.semes.reqops.domain.knowledge.entity.KnowledgeEntry; import com.semes.reqops.domain.knowledge.repository.KnowledgeEntryRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.HexFormat;
@Service @RequiredArgsConstructor public class ProjectKnowledgeService {private final KnowledgeEntryRepository repo;@Transactional public KnowledgeEntry project(Long projectId,String type,Long sourceId,Long versionId,String content){return repo.findByProjectIdAndSourceTypeAndSourceIdAndSourceVersionId(projectId,type,sourceId,versionId).orElseGet(()->repo.save(new KnowledgeEntry(projectId,type,sourceId,versionId,content,hash(content))));}private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
